// day.month.year typed by hand (also 1/2/26) -> 2026-02-01; "" -> ""; invalid -> null
crIso(text) {
  const t = (text || "").trim();
  if (!t) return "";
  const m = t.match(/^(\d{1,2})[./\-](\d{1,2})[./\-](\d{2}|\d{4})$/);
  if (!m) return null;
  let y = +m[3]; if (m[3].length === 2) y += 2000;
  const d = new Date(y, +m[2] - 1, +m[1]);
  if (d.getFullYear() !== y || d.getMonth() !== +m[2] - 1 || d.getDate() !== +m[1]) return null;
  return y + "-" + String(+m[2]).padStart(2, "0") + "-" + String(+m[1]).padStart(2, "0");
},
crFmt(d) { const p = n => String(n).padStart(2, "0"); return p(d.getDate()) + "." + p(d.getMonth() + 1) + "." + d.getFullYear(); },
crQuick(days) { const to = new Date(), from = new Date(); from.setDate(from.getDate() - days); this.cr.from = this.crFmt(from); this.cr.to = this.crFmt(to); },
crMonth() { const n = new Date(); this.cr.from = this.crFmt(new Date(n.getFullYear(), n.getMonth(), 1)); this.cr.to = this.crFmt(new Date(n.getFullYear(), n.getMonth() + 1, 0)); },
crQuery() {
  const from = this.crIso(this.cr.from), to = this.crIso(this.cr.to);
  if (from === null) { this.crMsg = "'מתאריך' לא תקין. כתוב יום.חודש.שנה, למשל 31.12.2026"; return null; }
  if (to === null) { this.crMsg = "'עד תאריך' לא תקין. כתוב יום.חודש.שנה, למשל 31.12.2026"; return null; }
  if (from && to && from > to) { this.crMsg = "'מתאריך' מאוחר מ'עד תאריך'"; return null; }
  this.crMsg = "";
  const q = new URLSearchParams({ type: this.cr.type });
  if (this.cr.type !== "visitors" && this.cr.type !== "infosec_summary") { if (from) q.set("date_from", from); if (to) q.set("date_to", to); }
  if (this.cr.type === "infosec" || this.cr.type === "expiry") { q.set("infosec", this.cr.infosec); q.set("sort", this.cr.sort); }
  if (this.cr.project) q.set("project", this.cr.project);
  if (this.cr.inviter && (this.cr.type === "invitees" || this.cr.type === "inviter_summary")) q.set("inviter", this.cr.inviter);
  if (this.cr.type === "activity") q.set("action", this.cr.action);
  if (this.cr.type === "expiry") {
    q.set("field", this.cr.field); q.set("status", this.cr.status);
    if (this.cr.status === "expiring" && this.cr.warn !== "" && this.cr.warn != null) q.set("warn_days", this.cr.warn);
  }
  return q.toString();
},
async crRun() {
